// ─────────────────────────── 8. analysis of morph tiles, and the segmentation it reports ───────────────────────────
const an = (base, tiles) => M.analyze(base, tiles);
for (const [base, tiles] of [["kitap", ["kitab", "y"]], ["mekdep", ["mekdep", "de"]], ["öý", ["öý", "ler", "de"]], ["öý", ["öý", "ümiz"]],
  ["gelmek", ["gel", "ýär", "in"]], ["gelmek", ["gel", "me", "ýär", "in"]], ["gelmek", ["gel", "ýär", "siň", "mi"]], ["gelmek", ["gel", "ýär", "mi", "ň"]],
  ["işlemek", ["işlä", "p"]], ["işlemek", ["işlä", "r"]], ["gelmek", ["gel", "mä", "ň"]], ["Mary", ["Mar", "a"]], ["eje", ["ejä", "m"]], ["eje", ["eje", "m"]],
  ["at", ["ad", "ym"]], ["at", ["at", "ym"]], ["görmek", ["gör", "dü", "m"]], ["ogul", ["ogl", "y"]], ["öý", ["öý", "ü", "n", "e"]], ["öý", ["öý", "dä", "ki"]],
  ["gitmek", ["gid", "ýär"]], ["talyp", ["talyp", "my"]], ["talyp", ["talyp", "my", "dy", "ň"]], ["gowy", ["gowu", "rak"]], ["stol", ["stol", "yň"]],
  ["dört", ["dörd", "ünji"]], ["Aýna", ["Aýna", "nyň"]], ["näme", ["nämä", "ni"]], ["bolmak", ["bol", "up", "dyr"]], ["dost", ["dost", "lug", "y"]]]) {
  check(`analyze ${base}: ${tiles.join("+")}`, () => an(base, tiles).ok, true, "check");
}
check("analyze mekdep+da: the engine builds mekdepde", () => { const r = an("mekdep", ["mekdep", "da"]); return [r.ok, r.reason, r.text]; }, [false, "form", "mekdepde"], "check");
check("analyze kitap+y: the engine builds kitaby", () => { const r = an("kitap", ["kitap", "y"]); return [r.reason, r.text]; }, ["form", "kitaby"], "check");
check("analyze Mary+a: the engine builds Mara", () => { const r = an("Mary", ["Mary", "a"]); return [r.reason, r.text]; }, ["form", "Mara"], "check");
check("analyze gör+di+m: the engine builds gördüm", () => { const r = an("görmek", ["gör", "di", "m"]); return [r.reason, r.text]; }, ["form", "gördüm"], "check");
check("analyze işle+p: the engine builds işläp", () => { const r = an("işlemek", ["işle", "p"]); return [r.reason, r.text]; }, ["form", "işläp"], "check");
check("analyze git+ýär: the engine builds gidýär", () => { const r = an("gitmek", ["git", "ýär"]); return [r.reason, r.text]; }, ["form", "gidýär"], "check");
check("analyze öý+üm+iz: a tile cuts a morpheme", () => { const r = an("öý", ["öý", "üm", "iz"]); return [r.reason, r.seg]; }, ["boundaries", "öý|ümiz"], "check");
check("seg: gel|ýär|in, öý|ü|n|e, Mar|a, işlä|p, o|n|y, ma|ň|a", () => [M.form("present", "gelmek", "men").seg, M.decline("öý", { poss: "ol", case: "dat" }).seg,
  M.decline("Mary", { case: "dat" }).seg, M.converb("işlemek").seg, M.decline("ol", { case: "acc" }).seg, M.decline("men", { case: "dat" }).seg],
  ["gel|ýär|in", "öý|ü|n|e", "Mar|a", "işlä|p", "o|n|y", "ma|ň|a"], "check");
check("forms() lists every slug with its negative and question", () =>
  ["copula-present", "present", "past", "future", "aorist", "necessitative", "ability", "past-copula", "optative", "imperative-3rd"].every(s =>
    M.formInfo(s) && M.formInfo(s + "-negative") && M.formInfo(s + "-question")), true, "check");
check("aliases: present-yar is present, maly is necessitative", () => [M.formInfo("present-yar").same, M.formInfo("maly").same], ["present", "necessitative"], "check");
check("no question of the 2nd-person imperative, no negative of the progressive", () => [M.formInfo("imperative-question"), M.formInfo("progressive-otyr-negative")], [null, null], "check");
check("persons a slug doesn't have give null", () => [M.form("imperative", "gelmek", "men"), M.form("optative", "gelmek", "ol"), M.form("assumption-an", "gelmek", "men")], [null, null, null], "check");

